from functools import lru_cache

def main():
    t = int(sys.stdin.readline())

    @lru_cache(maxsize=None)
    def can_win(n, move):
        if move > 10:
            return False
        if move % 2 == 1:  # Vanya's turn
            for delta in (1, -1):
                next_n = n + delta
                if next_n % 3 == 0:
                    return True
            for delta in (1, -1):
                next_n = n + delta
                if not can_win(next_n, move + 1):
                    return True
            return False
        else:  # Vova's turn
            for delta in (1, -1):
                next_n = n + delta
                if not can_win(next_n, move + 1):
                    return True
            return False

    for _ in range(t):
        n = int(sys.stdin.readline())
        result = can_win(n, 1)
        print("First" if result else "Second")

