class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        prefix = [0] * n
        for i in range(1, n):
            prefix[i] = prefix[i-1] | nums[i-1]

        suffix = [0] * n
        for i in range(n-2, -1, -1):
            suffix[i] = suffix[i+1] | nums[i+1]

        max_or = 0
        for i in range(n):
            current = (prefix[i] | suffix[i]) | (nums[i] << k)
            if current > max_or:
                max_or = current

        return max_or

