class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        n = len(nums)
        max_prod = float('-inf')
        for mask in range(1, 1 << n):
            product = 1
            for i in range(n):
                if (mask & (1 << i)):
                    product *= nums[i]
            if product > max_prod:
                max_prod = product
        return max_prod

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0  # base case: 0 characters, 0 extras

        for i in range(n):
            # Option 1: take the current character as extra
            dp[i + 1] = min(dp[i + 1], dp[i] + 1)

            # Option 2: check all words in the dictionary
            for word in dictionary:
                l = len(word)
                if i + l <= n and s[i:i+l] == word:
                    dp[i + l] = min(dp[i + l], dp[i])

        return dp[n]

