class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def subtract_one(s):
            digits = list(map(int, s))
            i = len(digits) - 1
            while i >= 0 and digits[i] == 0:
                digits[i] = 9
                i -= 1
            if i < 0:
                return "-1"  # According to problem constraints, this won't happen
            digits[i] -= 1
            s_new = ''.join(map(str, digits)).lstrip('0')
            return s_new or '0'

        def countUpTo(s: str, min_s: int, max_s: int) -> int:
            n = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, sm):
                if pos == n:
                    return 1 if (min_s <= sm <= max_s) else 0
                res = 0
                max_d = int(s[pos]) if tight else 9
                for d in range(0, max_d + 1):
                    new_tight = tight and (d == max_d)
                    res += dp(pos + 1, new_tight, sm + d)
                return res

            return dp(0, True, 0)

        lower = subtract_one(num1)
        a = countUpTo(num2, min_sum, max_sum)
        b = countUpTo(lower, min_sum, max_sum)
        return (a - b) % MOD

class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        colors = [0] * n
        count = 0
        answer = []

        for index, color in queries:
            old = colors[index]
            if old == color:
                answer.append(count)
                continue

            temp = 0
            # Check left neighbor
            if index > 0:
                left = colors[index - 1]
                if old != 0 and left == old:
                    temp -= 1
                if color != 0 and left == color:
                    temp += 1

            # Check right neighbor
            if index < n - 1:
                right = colors[index + 1]
                if old != 0 and right == old:
                    temp -= 1
                if color != 0 and right == color:
                    temp += 1

            count += temp
            colors[index] = color
            answer.append(count)

        return answer

class Solution:
    def sumOfPower(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        if n == 0:
            return 0

        F = [0] * n
        F[0] = nums[0] % MOD

        for i in range(1, n):
            F[i] = (2 * F[i-1] + nums[i]) % MOD

        total = 0
        for j in range(n):
            if j == 0:
                S_j = nums[j] % MOD
            else:
                S_j = (F[j-1] + nums[j]) % MOD
            term = (pow(nums[j], 2, MOD) * S_j) % MOD
            total = (total + term) % MOD

        return total

