class Solution:
    def punishmentNumber(self, n: int) -> int:
        total = 0
        for i in range(1, n + 1):
            square = i * i
            s = str(square)
            if self.can_split(s, i):
                total += square
        return total

    def can_split(self, s: str, target: int) -> bool:
        def helper(index, remaining):
            if index == len(s):
                return remaining == 0
            for end in range(index + 1, len(s) + 1):
                current = int(s[index:end])
                if current > remaining:
                    continue
                if helper(end, remaining - current):
                    return True
            return False

        return helper(0, target)

