class Solution:
    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0  # Base case: 0 cost to paint 0 walls

        for c, t in zip(cost, time):
            val = t + 1  # The value this wall contributes
            # Iterate backwards to prevent reuse of the same item
            for j in range(n, -1, -1):
                if dp[j] != float('inf'):
                    new_j = j + val
                    if new_j > n:
                        new_j = n
                    if dp[new_j] > dp[j] + c:
                        dp[new_j] = dp[j] + c

        return dp[n]

class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_vals = nums.copy()
        current_sum = sum(min_vals)
        min_total = current_sum

        for K in range(1, n):
            for j in range(n):
                pos = (j - K) % n
                candidate = nums[pos]
                if candidate < min_vals[j]:
                    current_sum += candidate - min_vals[j]
                    min_vals[j] = candidate
            total = current_sum + K * x
            if total < min_total:
                min_total = total

        return min_total

