class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False  # since n >=2

        max_num = max(nums)
        # Precompute smallest prime factors (SPF)
        N = max_num
        spf = [0] * (N + 1)
        spf[0], spf[1] = 0, 1
        for i in range(2, N+1):
            if spf[i] == 0:
                spf[i] = i
                for j in range(i*i, N+1, i):
                    if spf[j] == 0:
                        spf[j] = i

        parent = {}

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]  # Path compression
                u = parent[u]
            return u

        def union(u, v):
            pu = find(u)
            pv = find(v)
            if pu != pv:
                parent[pv] = pu

        for num in nums:
            n_val = num
            factors = set()
            while n_val > 1:
                p = spf[n_val]
                factors.add(p)
                while n_val % p == 0:
                    n_val //= p
            primes = list(factors)
            if not primes:
                continue  # shouldn't happen as num >=2
            # Add all primes to parent if not present
            for p in primes:
                if p not in parent:
                    parent[p] = p
            if len(primes) >= 1:
                first = primes[0]
                for p in primes[1:]:
                    union(first, p)

        if not parent:
            return False  # shouldn't happen as all nums >=2

        roots = list(parent.keys())
        root0 = find(roots[0])
        for r in roots[1:]:
            if find(r) != root0:
                return False
        return True

class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        start = 0
        while start < n and s[start] == 'a':
            start += 1
        if start == n:
            return 'z' * n
        end = start
        for i in range(start, n):
            if s[i] == 'a':
                break
            end = i
        res = list(s)
        for i in range(start, end + 1):
            res[i] = chr(ord(res[i]) - 1)
        return ''.join(res)

