class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        groups = defaultdict(list)
        for idx, num in enumerate(nums):
            groups[num].append(idx)

        max_result = 0
        for num, indices in groups.items():
            m = len(indices)
            a = [indices[i] - i for i in range(m)]
            left = 0
            current_max = 0
            for right in range(m):
                while a[right] - a[left] > k:
                    left += 1
                current_length = right - left + 1
                if current_length > current_max:
                    current_max = current_length
            if current_max > max_result:
                max_result = current_max
        return max_result

class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        marbles = set(nums)
        for f, t in zip(moveFrom, moveTo):
            if f != t and f in marbles:
                marbles.remove(f)
                marbles.add(t)
        return sorted(marbles)

class Solution:
