class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        if n == 0:
            return 0

        # Precompute compatibility matrix
        compat = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    a, b = nums[i], nums[j]
                    if a % b == 0 or b % a == 0:
                        compat[i][j] = True

        # Initialize DP table
        dp = [[0] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 1

        # Process each mask
        for mask in range(1 << n):
            for last in range(n):
                if dp[mask][last] == 0:
                    continue
                for j in range(n):
                    if not (mask & (1 << j)) and compat[last][j]:
                        new_mask = mask | (1 << j)
                        dp[new_mask][j] = (dp[new_mask][j] + dp[mask][last]) % MOD

        full_mask = (1 << n) - 1
        return sum(dp[full_mask][i] for i in range(n)) % MOD

