class Solution:
    def longestString(self, x: int, y: int, z: int) -> int:
        INF = -sys.maxsize
        # Initialize DP array: dp[a][b][c][last]
        dp = [[[[INF for _ in range(3)] for __ in range(z+1)] for ___ in range(y+1)] for ____ in range(x+1)]
        dp[x][y][z][2] = 0  # Initial state: all counts remaining, last is 2 (none)

        q = deque()
        q.append((x, y, z, 2))

        while q:
            a, b, c, last = q.popleft()
            current = dp[a][b][c][last]

            if last == 0:  # last character was A
                if b > 0:
                    newa, newb, newc = a, b-1, c
                    newlast = 1
                    new_val = current + 2
                    if new_val > dp[newa][newb][newc][newlast]:
                        dp[newa][newb][newc][newlast] = new_val
                        q.append((newa, newb, newc, newlast))
            elif last == 1:  # last character was B
                if a > 0:
                    newa, newb, newc = a-1, b, c
                    newlast = 0
                    new_val = current + 2
                    if new_val > dp[newa][newb][newc][newlast]:
                        dp[newa][newb][newc][newlast] = new_val
                        q.append((newa, newb, newc, newlast))
                if c > 0:
                    newa, newb, newc = a, b, c-1
                    newlast = 1
                    new_val = current + 2
                    if new_val > dp[newa][newb][newc][newlast]:
                        dp[newa][newb][newc][newlast] = new_val
                        q.append((newa, newb, newc, newlast))
            elif last == 2:  # initial state
                if a > 0:
                    newa, newb, newc = a-1, b, c
                    newlast = 0
                    new_val = current + 2
                    if new_val > dp[newa][newb][newc][newlast]:
                        dp[newa][newb][newc][newlast] = new_val
                        q.append((newa, newb, newc, newlast))
                if b > 0:
                    newa, newb, newc = a, b-1, c
                    newlast = 1
                    new_val = current + 2
                    if new_val > dp[newa][newb][newc][newlast]:
                        dp[newa][newb][newc][newlast] = new_val
                        q.append((newa, newb, newc, newlast))
                if c > 0:
                    newa, newb, newc = a, b, c-1
                    newlast = 1
                    new_val = current + 2
                    if new_val > dp[newa][newb][newc][newlast]:
                        dp[newa][newb][newc][newlast] = new_val
                        q.append((newa, newb, newc, newlast))

        max_len = 0
        for a in range(x+1):
            for b in range(y+1):
                for c in range(z+1):
                    for last in range(3):
                        if dp[a][b][c][last] > max_len:
                            max_len = dp[a][b][c][last]
        return max_len

