class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        dp = [-float('inf')] * n
        dp[-1] = 0  # Base case: at the end, 0 jumps needed

        for i in range(n - 2, -1, -1):
            current_max = -float('inf')
            for j in range(i + 1, n):
                diff = nums[j] - nums[i]
                if -target <= diff <= target:
                    if dp[j] != -float('inf'):
