class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(x: str, y: str) -> str:
            def max_overlap(a_str: str, b_str: str) -> int:
                max_possible = min(len(a_str), len(b_str))
                for k in range(max_possible, 0, -1):
                    if a_str.endswith(b_str[:k]):
                        return k
                return 0

            k_xy = max_overlap(x, y)
            merged_xy = x + y[k_xy:]

            k_yx = max_overlap(y, x)
            merged_yx = y + x[k_yx:]

            if len(merged_xy) < len(merged_yx):
                return merged_xy
            elif len(merged_yx) < len(merged_xy):
                return merged_yx
            else:
                return min(merged_xy, merged_yx)

        permutations = itertools.permutations([a, b, c])
        candidates = []
        for perm in permutations:
            first = perm[0]
            second = perm[1]
            third = perm[2]
            temp = merge(first, second)
            merged = merge(temp, third)
            candidates.append(merged)

        candidates.sort(key=lambda s: (len(s), s))
        return candidates[0]

class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        N = len(s)
        # Precompute divisors for each possible length L
        divisors = [[] for _ in range(201)]
        for L in range(2, 201):
            for d in range(1, L):
                if L % d == 0:
                    divisors[L].append(d)

        # Precompute the cost for all substrings [i..j]
        cost = [[0] * N for _ in range(N)]
        for i in range(N):
            for j in range(i + 1, N):
                L = j - i + 1
                min_changes = float('inf')
                for d in divisors[L]:
                    current = 0
                    m = L // d
                    for g in range(d):
                        changes_g = 0
                        for a in range(m // 2):
                            pos1 = g + a * d
                            pos2 = g + (m - 1 - a) * d
                            if s[i + pos1] != s[i + pos2]:
                                changes_g += 1
                        current += changes_g
                    if current < min_changes:
                        min_changes = current
                cost[i][j] = min_changes

        # Dynamic programming to find the minimal changes for partitioning into k substrings
        INF = float('inf')
        dp = [[INF] * (k + 1) for _ in range(N + 1)]
        dp[0][0] = 0
        for m in range(1, k + 1):
            for i in range(1, N + 1):
                if m == 1:
                    if i >= 2:
                        dp[i][m] = cost[0][i - 1]
                    else:
                        dp[i][m] = INF
                else:
                    dp[i][m] = INF
                    start_j = 2 * (m - 1)
                    end_j = i - 2
                    if start_j > end_j:
                        continue
                    for j in range(start_j, end_j + 1):
                        if dp[j][m - 1] + cost[j][i - 1] < dp[i][m]:
                            dp[i][m] = dp[j][m - 1] + cost[j][i - 1]

        return dp[N][k]

