class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        MOD = 10**9 + 7
        powers = []
        k = 1
        while True:
            pow_val = k ** x
            if pow_val > n:
                break
            powers.append(pow_val)
            k += 1
        dp = [0] * (n + 1)
        dp[0] = 1
        for p in powers:
            for i in range(n, p - 1, -1):
                dp[i] = (dp[i] + dp[i - p]) % MOD
        return dp[n] % MOD

class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        valid = set()
        for k in range(7):
            num = 5 ** k
            bin_str = bin(num)[2:]  # Get binary without '0b' prefix
            valid.add(bin_str)

        n = len(s)
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0  # Base case: 0 characters need 0 partitions

        for i in range(1, n + 1):
            for j in range(i):
                substr = s[j:i]
                if substr[0] == '0':
                    continue  # Skip leading zeros
                if substr in valid:
                    if dp[j] + 1 < dp[i]:
                        dp[i] = dp[j] + 1

        return dp[n] if dp[n] != INF else -1

