        for right in range(n):
            new_left = left
            for L in range(1, 11):
                start = right - L + 1
                if start < 0:
                    continue
                substring = word[start:right+1]
                if substring in forbidden_set:
                    candidate = start + 1
                    if candidate > new_left:
                        new_left = candidate
            left = new_left
            current_length = right - left + 1
            if current_length > max_len:
                max_len = current_length
        return max_len

