class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        first = nums[0]
        if first % 2 == 0:
            even = first
            odd = float('-inf')
        else:
            even = float('-inf')
            odd = first

        for num in nums[1:]:
            if num % 2 == 0:
                # Current number is even
                cand_even = max(even + num, odd + num - x)
                new_even = max(even, cand_even)
                new_odd = odd
            else:
                # Current number is odd
                cand_odd = max(odd + num, even + num - x)
                new_odd = max(odd, cand_odd)
                new_even = even
            even, odd = new_even, new_odd

        return max(even, odd)

