        for i, num in enumerate(nums):
            num_indices[num].append(i)

        min_time = float('inf')
        for num, indices in num_indices.items():
            m = len(indices)
            if m == 1:
                current_max_gap = n
            else:
                current_max_gap = 0
                # Check gaps between consecutive indices
                for i in range(1, m):
                    gap = indices[i] - indices[i-1]
                    if gap > current_max_gap:
