class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def subtract_one(s):
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return '0'
            s_list[i] = str(int(s_list[i]) - 1)
            new_str = ''.join(s_list)
            while len(new_str) > 1 and new_str[0] == '0':
                new_str = new_str[1:]
            return new_str

        def count(s):
            n = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev_digit, is_tight):
                if pos == n:
                    return 1
                res = 0
                max_d = int(s[pos]) if is_tight else 9
                for d in range(0, max_d + 1):
                    new_is_tight = is_tight and (d == max_d)
                    if prev_digit == -1:  # leading_zero is True
                        if d == 0:
                            new_prev = -1
                        else:
                            new_prev = d
                        res += dp(pos + 1, new_prev, new_is_tight)
                    else:  # leading_zero is False
                        if abs(d - prev_digit) != 1:
                            continue
                        new_prev = d
                        res += dp(pos + 1, new_prev, new_is_tight)
                    res %= MOD
                return res % MOD

            total = dp(0, -1, True)
            return total % MOD

        low_minus_1 = subtract_one(low)
        ans = (count(high) - count(low_minus_1)) % MOD
        return ans if ans >= 0 else ans + MOD

