class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        sorted_list = []
        min_diff = float('inf')
        n = len(nums)
        for i in range(n):
            if i >= x:
                val = nums[i - x]
                bisect.insort(sorted_list, val)
            # Check current element with the sorted list
            if sorted_list:
                current_val = nums[i]
                idx = bisect.bisect_left(sorted_list, current_val)
                # Check closest elements
                if idx < len(sorted_list):
                    min_diff = min(min_diff, abs(current_val - sorted_list[idx]))
