class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:

        def count_up_to(x):
            if x < 1:
                return 0
            digits = list(map(int, str(x)))
            n = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, balance, mod, tight, leading_zero):
                if pos == n:
                    return 1 if (not leading_zero and balance == 0 and mod == 0) else 0
                res = 0
                max_d = digits[pos] if tight else 9
                for d in range(0, max_d + 1):
                    new_tight = tight and (d == max_d)
                    new_leading_zero = leading_zero and (d == 0)
                    new_balance = balance
                    new_mod = mod
                    if not new_leading_zero:
                        # digit contributes to balance and mod
                        if d % 2 == 0:
                            new_balance += 1
                        else:
                            new_balance -= 1
                        new_mod = (mod * 10 + d) % k
                    res += dp(pos + 1, new_balance, new_mod, new_tight, new_leading_zero)
                return res

            return dp(0, 0, 0, True, True)

        return count_up_to(high) - count_up_to(low - 1)

