class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        if n != len(t):
            return 0

        text = s + s

        def compute_lps(pattern):
            lps = [0] * len(pattern)
            length = 0
            i = 1
            while i < len(pattern):
                if pattern[i] == pattern[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                else:
                    if length != 0:
                        length = lps[length - 1]
                    else:
                        lps[i] = 0
                        i += 1
            return lps

        lps = compute_lps(t)

        def kmp_search_all(text, pattern, lps):
            occurrences = []
            i = 0
            j = 0
            while i < len(text):
                if text[i] == pattern[j]:
                    i += 1
                    j += 1
                    if j == len(pattern):
                        occurrences.append(i - j)
                        j = lps[j - 1]
                else:
                    if j != 0:
                        j = lps[j - 1]
                    else:
                        i += 1
            return occurrences

        occurrences = kmp_search_all(text, t, lps)
        if not occurrences:
            return 0

        R = set()
        for pos in occurrences:
            r = pos % n
            R.add(r)

        total = 0
        for r in R:
            if r == 0:
                term1 = pow(n - 1, k, MOD)
                term2 = pow(-1, k, MOD)
                term2 = (n - 1) * term2 % MOD
                numerator = (term1 + term2) % MOD
            else:
                term1 = pow(n - 1, k, MOD)
                term2 = pow(-1, k, MOD)
                numerator = (term1 - term2) % MOD

            denominator = n
            inv_denominator = pow(denominator, MOD - 2, MOD)
            ans = numerator * inv_denominator % MOD
            total = (total + ans) % MOD

        return total

