class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        cnt = [0] * 31
        for num in nums:
            exponent = int(math.log2(num))
            cnt[exponent] += 1
        total = sum(nums)
        if total < target:
            return -1

        carry = 0
        operations = 0
        for i in range(31):
            current = cnt[i] + carry
            required = 1 if (target & (1 << i)) else 0

            if required:
                if current >= 1:
                    current -= 1
                else:
                    j = i + 1
                    while j < 31 and cnt[j] == 0:
                        j += 1
                    if j >= 31:
                        return -1
                    operations += (j - i)
                    cnt[j] -= 1
                    current = 1  # After splitting, we have 1 at current i

            # Update carry and cnt[i] for next iteration
            carry = current // 2
            cnt[i] = current % 2

        return operations

class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        n = len(receiver)
        max_level = 60  # Sufficient as 2^60 is much larger than 1e10

        # Initialize jump and sum tables
        jmp = [[0] * n for _ in range(max_level)]
        sum_table = [[0] * n for _ in range(max_level)]

        # Base case: level 0
        for u in range(n):
            jmp[0][u] = receiver[u]
            sum_table[0][u] = receiver[u]

        # Fill tables for higher levels
        for j in range(1, max_level):
            for u in range(n):
                prev_node = jmp[j-1][u]
                jmp[j][u] = jmp[j-1][prev_node]
                sum_table[j][u] = sum_table[j-1][u] + sum_table[j-1][prev_node]

        max_f = 0
        for x in range(n):
            total = 0
            current_node = x
            # Iterate over all bits to compute the sum for k steps
            for j in reversed(range(max_level)):
                if k & (1 << j):
                    total += sum_table[j][current_node]
                    current_node = jmp[j][current_node]
            current_f = x + total
            if current_f > max_f:
                max_f = current_f

        return max_f

