    def minOperations(self, s1: str, s2: str, x: int) -> int:
        diffs = []
        n = len(s1)
        for i in range(n):
            if s1[i] != s2[i]:
                diffs.append(i)
        m = len(diffs)
        if m % 2 != 0:
            return -1
        if m == 0:
            return 0

        dp = [float('inf')] * (m + 1)
        dp[0] = 0

        for i in range(2, m + 1, 2):
            for j in range(0, i, 2):
                cost = dp[j] + min(diffs[i-1] - diffs[j], x)
                if cost < dp[i]:
                    dp[i] = cost

        return dp[m]

