class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        sorted_nums = sorted(nums)
        if nums == sorted_nums:
            return 0

        pivot = -1
        count = 0
        for i in range(n):
            next_i = (i + 1) % n
            if nums[i] > nums[next_i]:
                count += 1
                pivot = i

        if count != 1:
            return -1

        rotated = nums[pivot+1:] + nums[:pivot+1]
        if rotated == sorted_nums:
            return n - (pivot + 1)
        else:
            return -1

class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        min_ops = n  # The case where all digits are deleted to get 0

        # Check the case where the number ends with a single '0'
        if '0' in num:
            min_ops = min(min_ops, n - 1)

        # Check all possible two-digit endings for divisibility by 25
        targets = ["00", "25", "50", "75"]
        for target in targets:
            first, second = target[0], target[1]
            current_min = float('inf')
            # Iterate over possible positions for the second character
            for j in range(n-1, -1, -1):
                if num[j] == second:
                    # Find the closest occurrence of the first character before j
                    for i in range(j-1, -1, -1):
                        if num[i] == first:
                            steps = (n - i - 2)
                            if steps < current_min:
                                current_min = steps
                            break  # Found the closest possible i, move to next j
            if current_min != float('inf'):
                min_ops = min(min_ops, current_min)

        return min_ops

