def square_free_part(n: int) -> int:
    if n == 0:
        return 0
    res = 1
    # Factor out 2
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    if count % 2 != 0:
        res *= 2
    # Check odd factors up to sqrt(n)
    i = 3
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count % 2 != 0:
            res *= i
        i += 2
    # If remaining n is a prime
    if n > 1:
        res *= n
    return res

