        dp = [float('-inf')] * (target + 1)
        dp[0] = 0  # Base case: sum 0 with 0 elements

        for num in nums:
            # Iterate from target down to 'num' to avoid reusing the same element multiple times
            for s in range(target, num - 1, -1):
                if dp[s - num] != float('-inf'):
