class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        def compute_min_length(arr, X):
            min_len = float('inf')
            current_sum = 0
            left = 0
            for right in range(len(arr)):
                current_sum += arr[right]
                while current_sum > X and left <= right:
                    current_sum -= arr[left]
                    left += 1
                if current_sum == X:
                    min_len = min(min_len, right - left + 1)
            return min_len if min_len != float('inf') else float('inf')

        S = sum(nums)
        n = len(nums)
        if target == 0:
            return 0
        q, r = divmod(target, S)
        if r == 0:
            return q * n
        else:
            doubled = nums + nums
            L = compute_min_length(doubled, r)
            M_val = S - r
            M = compute_min_length(doubled, M_val)
            option1 = q * n + L
            if M == float('inf'):
                option2 = float('inf')
            else:
                option2 = (q + 1) * n - M
            res = min(option1, option2)
            if res == float('inf'):
                return -1
            else:
                return int(res)

