    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)
        if k == 0:
            return ""
        # Compute prefix sum of 1's
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + (1 if s[i] == '1' else 0)

        candidates = []
        for i in range(n):
            for j in range(i, n):
                current_ones = prefix[j+1] - prefix[i]
                if current_ones == k:
                    substr = s[i:j+1]
                    candidates.append(substr)

        if not candidates:
            return ""

        min_len = min(len(sub) for sub in candidates)
        min_candidates = [sub for sub in candidates if len(sub) == min_len]
        return min(min_candidates)

