            max_i[j] = max(max_i[j-1], nums[j-1])

        val = [0] * n
        for j in range(1, n):
            val[j] = max_i[j] - nums[j]

        max_val_upto = [-float('inf')] * n
        for j in range(1, n):
            if j == 1:
                max_val_upto[j] = val[j]
            else:
                max_val_upto[j] = max(max_val_upto[j-1], val[j])

        max_candidate = -float('inf')
        for k in range(2, n):
            current_max_val = max_val_upto[k-1]
            product = current_max_val * nums[k]
            if product > max_candidate:
                max_candidate = product

        return max_candidate if max_candidate > 0 else 0

