        counts = list(Counter(nums).values())
        if not counts:
            return 0
        max_count = max(counts)
        low, high = 1, max_count
        best_k = 1  # At least possible with k=1

        while low <= high:
            mid = (low + high) // 2
            if self.is_possible(mid, counts):
                best_k = mid
                low = mid + 1
            else:
                high = mid - 1

        total = 0
        for c in counts:
            total += (c + best_k - 1) // best_k
        return total

    def is_possible(self, k: int, counts: List[int]) -> bool:
        if k == 1:
            return True
        for c in counts:
            if c < (k - 1):
                return False
            m_min = (c + k - 1) // k
            m_max = c // (k - 1)
            if m_min > m_max:
                return False
        return True

