class FenwickTree:
    def __init__(self, size):
        self.n = size
        self.tree = [-float('inf')] * (self.n + 1)  # 1-based indexing

    def update(self, idx, value):
        while idx <= self.n:
            if value > self.tree[idx]:
                self.tree[idx] = value
            else:
                break  # No need to proceed further if not better
            idx += idx & -idx

    def query(self, idx):
        res = -float('inf')
        while idx > 0:
            res = max(res, self.tree[idx])
            idx -= idx & -idx
        return res

class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        if not nums:
            return 0
        n = len(nums)
        k_list = [nums[i] - i for i in range(n)]
        sorted_unique = sorted(set(k_list))
        M = len(sorted_unique)
        ft = FenwickTree(M)
        current_max = -float('inf')

        for i in range(n):
            k_i = nums[i] - i
            pos = bisect.bisect_right(sorted_unique, k_i)
            r = pos - 1
            fenwick_idx = r + 1
            max_prev = ft.query(fenwick_idx)
            dp_i = nums[i] + max(max_prev, 0)
            if dp_i > current_max:
                current_max = dp_i
            ft.update(fenwick_idx, dp_i)

        return current_max

