        for left in range(0, n - f + 1):
            right = left + f - 1
            m = left + (f - 1) // 2
            part1 = nums[m] * (m - left + 1) - (prefix[m + 1] - prefix[left])
            part2 = (prefix[right + 1] - prefix[m + 1]) - nums[m] * (right - m)
            total = part1 + part2
            if total <= k:
                return True
        return False

