class Solution:
    def canMakePalindromeQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        n = len(s)
        half = n // 2
        first_counts = [0] * 26
        second_counts = [0] * 26

        for i in range(half):
            first_counts[ord(s[i]) - ord('a')] += 1
        for i in range(half, n):
            second_counts[ord(s[i]) - ord('a')] += 1

        if first_counts != second_counts:
            return [False] * len(queries)

        bad = [False] * half
        for i in range(half):
            if s[i] != s[n - 1 - i]:
                bad[i] = True

        prefix = [0] * (half + 1)
        for i in range(half):
            prefix[i + 1] = prefix[i] + (1 if bad[i] else 0)

        res = []
        for q in queries:
            a, b, c, d = q
            has_bad = False

            # Case1: i <a and j <c
            L1 = (n - 1 - c) + 1
            R1 = a - 1
            l1 = max(L1, 0)
            r1 = min(R1, half - 1)
            if l1 <= r1:
                cnt = prefix[r1 + 1] - prefix[l1]
                if cnt > 0:
                    has_bad = True
            if has_bad:
                res.append(False)
                continue

            # Case2: i <a and j> d
            max_i = (n - 1 - d) - 1
            R2 = min(a - 1, max_i)
            l2 = 0
            r2 = min(R2, half - 1)
            if r2 >= 0 and r2 >= l2:
                cnt = prefix[r2 + 1] - prefix[l2]
                if cnt > 0:
                    has_bad = True
            if has_bad:
                res.append(False)
                continue

            # Case3: i> b and j <c
            L3 = max(b + 1, (n - 1 - c) + 1)
            r3 = half - 1
            l3 = L3
            if l3 <= r3:
                cnt = prefix[r3 + 1] - prefix[l3]
                if cnt > 0:
                    has_bad = True
            if has_bad:
                res.append(False)
                continue

            # Case4: i> b and j> d
            L4 = b + 1
            R4 = (n - 1 - d) - 1
            l4 = L4
            r4 = min(R4, half - 1)
            if l4 <= r4 and l4 >= 0:
                cnt = prefix[r4 + 1] - prefix[l4]
                if cnt > 0:
                    has_bad = True

            res.append(not has_bad)

        return res

