        for i in range(n):
            prefix[i+1] = prefix[i] + (1 if s[i] in vowels else 0)
        count = 0
        for start in range(n):
            for end in range(start, n):
                length = end - start + 1
                if length % 2 != 0:
                    continue
                required = length // 2
