class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        first = {}
        last = {}
        for i, num in enumerate(nums):
            if num not in first:
                first[num] = i
                last[num] = i
            else:
                last[num] = i

        intervals = []
        for num in first:
            intervals.append([first[num], last[num]])

        intervals.sort()  # Sort by starting index

        merged = []
        for s, e in intervals:
            if not merged:
                merged.append([s, e])
            else:
                last_s, last_e = merged[-1]
                if s <= last_e:
                    merged[-1][1] = max(e, last_e)
                else:
                    merged.append([s, e])

        m = len(merged)
        MOD = 10**9 + 7
        return pow(2, m - 1, MOD)

