class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        sorted_pairs = sorted((nums[i], i) for i in range(n))

        groups = []
        if not sorted_pairs:
            return []

        current_group = [sorted_pairs[0]]
        for i in range(1, len(sorted_pairs)):
            prev_val = sorted_pairs[i-1][0]
            curr_val = sorted_pairs[i][0]
            if curr_val - prev_val > limit:
                groups.append(current_group)
                current_group = [sorted_pairs[i]]
            else:
                current_group.append(sorted_pairs[i])
        groups.append(current_group)  # Add the last group

        res = [0] * n
        for group in groups:
            indices = [pair[1] for pair in group]
            sorted_indices = sorted(indices)
            for i in range(len(group)):
                res[sorted_indices[i]] = group[i][0]

        return res

