class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        segments = []
        current_segment = []
        for c in word:
            if not current_segment:
                current_segment.append(c)
            else:
                prev_c = current_segment[-1]
                if abs(ord(c) - ord(prev_c)) > 2:
                    segments.append(''.join(current_segment))
                    current_segment = [c]
                else:
                    current_segment.append(c)
        if current_segment:
            segments.append(''.join(current_segment))

        total = 0
        for seg in segments:
            n = len(seg)
            for m in range(1, 27):
                L = m * k
                if L > n:
                    continue
                freq = [0] * 26
                # Initialize first window
                valid = True
                cnt = 0
                for i in range(L):
                    c = seg[i]
                    idx = ord(c) - ord('a')
                    freq[idx] += 1
                # Check initial window
                valid = True
                cnt = 0
                for f in freq:
                    if f != 0:
                        if f != k:
                            valid = False
                            break
                        cnt += 1
                if valid and cnt == m:
                    total += 1
                # Slide the window
                for i in range(1, n - L + 1):
                    # Remove left character
                    left_char = seg[i-1]
                    left_idx = ord(left_char) - ord('a')
                    freq[left_idx] -= 1
                    # Add new right character
                    right_char = seg[i + L - 1]
                    right_idx = ord(right_char) - ord('a')
                    freq[right_idx] += 1
                    # Check validity
                    valid = True
                    cnt = 0
                    for f in freq:
                        if f != 0:
                            if f != k:
                                valid = False
                                break
                            cnt += 1
                    if valid and cnt == m:
                        total += 1
        return total

