class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def is_palindrome(x):
            s = str(x)
            return s == s[::-1]

        def generate_candidates(m):
            candidates = set()
            s = str(m)
            n = len(s)
            half = (n + 1) // 2
            prefix = s[:half]
            for delta in (-1, 0, 1):
                new_p = int(prefix) + delta
                if new_p <= 0:
                    continue
                new_prefix = str(new_p)
                if n % 2 == 0:
                    candidate_str = new_prefix + new_prefix[::-1]
                else:
                    candidate_str = new_prefix + new_prefix[:-1][::-1]
                candidate = int(candidate_str)
                if 0 < candidate < 10**9:
                    candidates.add(candidate)
            # Check m itself
            if is_palindrome(m):
                candidates.add(m)
            # Check m ±1
            for delta in (-1, 1):
                candidate = m + delta
                if 0 < candidate < 10**9 and is_palindrome(candidate):
                    candidates.add(candidate)
            return candidates

        nums_sorted = sorted(nums)
        n = len(nums_sorted)
        median = nums_sorted[n // 2]
        candidates = generate_candidates(median)

        min_cost = float('inf')
        for y in candidates:
            cost = sum(abs(num - y) for num in nums)
            if cost < min_cost:
                min_cost = cost
        return min_cost

