class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0
        visited = set()
        queue = deque()
        queue.append((x, 0))
        visited.add(x)

        while queue:
            current, steps = queue.popleft()
            if current == y:
                return steps
            next_nums = []
            if current % 11 == 0:
                next_nums.append(current // 11)
            if current % 5 == 0:
                next_nums.append(current // 5)
            if current > 1:
                next_nums.append(current - 1)
            next_nums.append(current + 1)

            for num in next_nums:
                if num > 0 and num not in visited:
                    visited.add(num)
                    queue.append((num, steps + 1))

        return -1  # The problem constraints ensure this is unreachable

