class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        s_val = int(s)
        L = len(s)
        pow_L = 10 ** L

        if s_val > finish:
            return 0

        X_min = max(0, (start - s_val + pow_L - 1) // pow_L)
        X_max = (finish - s_val) // pow_L

        if X_max < X_min:
            return 0

        def count_upto(n):
            if n < 0:
                return 0
            s_n = str(n)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, leading_zero):
                if pos == len(s_n):
                    return 1
                res = 0
                max_d = int(s_n[pos]) if tight else 9
                for d in range(0, max_d + 1):
                    new_tight = tight and (d == max_d)
                    new_leading = leading_zero and (d == 0)
                    if leading_zero and d == 0:
                        res += dp(pos + 1, new_tight, True)
                    else:
                        if d > limit:
                            continue
                        res += dp(pos + 1, new_tight, False)
                return res
            return dp(0, True, True)

        total = count_upto(X_max) - count_upto(X_min - 1)
        return total

