class Solution:
    def minOrAfterOperations(self, nums: List[int], k: int) -> int:
        n = len(nums)
        result = 0
        for num in nums:
            result |= num

        for bit in range(29, -1, -1):
            if (result & (1 << bit)) == 0:
                continue  # Bit is already off, no need to process

            # Compute the number of clusters of unsets for this bit
            clusters = 0
            current_in_cluster = False
            for num in nums:
                if (num & (1 << bit)) == 0:
                    if not current_in_cluster:
                        clusters += 1
                        current_in_cluster = True
                else:
                    current_in_cluster = False

            if clusters == 0:
                continue  # No way to turn off this bit

            if clusters <= (n - k):
                # Can turn off this bit
                result ^= (1 << bit)

        return result

