class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)
        low = 1
        high = m
        ans = -1

        def is_possible(s):
            last_occurrence = [-1] * n
            for t in range(s):
                idx = changeIndices[t] - 1  # Convert to 0-based index
                last_occurrence[idx] = t + 1  # Problem's time is t+1

            # Check if any index is missing
            for j in range(n):
                if last_occurrence[j] == -1:
                    return False

            T_list = []
            for j in range(n):
                T = last_occurrence[j]
                num = nums[j]
                T_list.append((T, num))

            T_list.sort()

            total_decrements = sum(nums)
            if total_decrements + n > s:
                return False

            for k in range(n):
                T, num = T_list[k]
                available = T - 1 - k
                if num > available:
                    return False
            return True

        while low <= high:
            mid = (low + high) // 2
            if is_possible(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

