class Solution:
    def sumOfPowers(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)
        if n < k:
            return 0

        # Collect all possible differences
        diffs = set()
        for i in range(n):
            for j in range(i + 1, n):
                diffs.add(nums[j] - nums[i])
        diffs = sorted(diffs)

        def compute_f(d):
            dp = [[0] * (k + 1) for _ in range(n)]
            prefix = [[0] * (k + 1) for _ in range(n)]

            for i in range(n):
                dp[i][1] = 1
                for j in range(1, k + 1):
                    if i == 0:
                        prefix[i][j] = dp[i][j]
                    else:
                        prefix[i][j] = prefix[i-1][j] + dp[i][j]

            for j in range(2, k + 1):
                for i in range(n):
                    target = nums[i] - d
                    low, high = 0, i - 1
                    m_max = -1
                    while low <= high:
                        mid = (low + high) // 2
                        if nums[mid] <= target:
                            m_max = mid
                            low = mid + 1
                        else:
                            high = mid - 1
                    if m_max == -1:
                        dp[i][j] = 0
                    else:
                        dp[i][j] = prefix[m_max][j-1]
                    # Update prefix array for current j
                    if i == 0:
                        prefix[i][j] = dp[i][j]
                    else:
                        prefix[i][j] = prefix[i-1][j] + dp[i][j]

            total = 0
            for i in range(n):
                total += dp[i][k]
            return total

        # Precompute f(d) for all differences
        f_dict = {}
        for d in diffs:
            f_dict[d] = compute_f(d)

        # Calculate the total sum using the sorted differences in reverse
        total_sum = 0
        prev = 0
        for d in reversed(diffs):
            current_f = f_dict[d]
            count = current_f - prev
            total_sum += d * count
            prev = current_f

        return total_sum % MOD

