class Solution:
    def sumOfPower(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        new_nums = [x for x in nums if x <= k]
        m = len(new_nums)
        n = len(nums)

        # Initialize DP table: dp[s][t] is the number of subsets with sum s and size t
        dp = [[0] * (m + 1) for _ in range(k + 1)]
        dp[0][0] = 1  # base case: empty subset

        for x in new_nums:
            # Iterate backwards to avoid overwriting values we need
            for s in range(k, -1, -1):
                for t in range(m, -1, -1):
                    if dp[s][t]:
                        new_s = s + x
                        new_t = t + 1
                        if new_s <= k and new_t <= m:
                            dp[new_s][new_t] = (dp[new_s][new_t] + dp[s][t]) % MOD

        total = 0
        for t in range(m + 1):
            if dp[k][t]:
                term = dp[k][t] * pow(2, n - t, MOD)
                total = (total + term) % MOD

        return total

