class Solution:
    def minimizeStringValue(self, s: str) -> str:
        counts = [0] * 26
        k = 0
        for c in s:
            if c != '?':
                counts[ord(c) - ord('a')] += 1
            else:
                k += 1

        heap = []
        for i in range(26):
            heapq.heappush(heap, (counts[i], i))

        x = [0] * 26
        for _ in range(k):
            val, c_idx = heapq.heappop(heap)
            x[c_idx] += 1
            new_val = val + 1
            heapq.heappush(heap, (new_val, c_idx))

        selected = []
        for i in range(26):
            selected += [chr(i + ord('a'))] * x[i]
        selected.sort()

        res = []
        ptr = 0
        for c in s:
            if c == '?':
                res.append(selected[ptr])
                ptr += 1
            else:
                res.append(c)
        return ''.join(res)

