        n = len(arr)
        answer = [''] * n

        # Precompute forbidden substrings for each index
        forbidden = [set() for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if j != i:
                    s = arr[j]
                    m = len(s)
                    for l in range(1, m + 1):
                        for start in range(m - l + 1):
                            substr = s[start:start+l]
                            forbidden[i].add(substr)

        # Determine the answer for each string
        for i in range(n):
            current = arr[i]
            found = False
            for l in range(1, len(current) + 1):
                subs = []
                max_start = len(current) - l
                for start in range(max_start + 1):
                    subs.append(current[start:start+l])
                subs_sorted = sorted(subs)
                for s in subs_sorted:
                    if s not in forbidden[i]:
                        answer[i] = s
                        found = True
                        break
                if found:
                    break

        return answer

