        freq = list(Counter(word).values())
        if not freq:
            return 0
        max_freq = max(freq)
        min_deletions = float('inf')

        for L in range(0, max_freq + 1):
            current = 0
            upper = L + k
            for f in freq:
                if f < L:
                    current += f
                else:
                    if f > upper:
                        current += (f - upper)
            if current < min_deletions:
                min_deletions = current

        return min_deletions

