class Solution:
    def mostFrequentIDs(self, nums: List[int], freq: List[int]) -> List[int]:
        count = {}  # Maps ID to its current count
        count_freq = {}  # Maps count values to the number of IDs with that count
        heap = []
        ans = []

        for i in range(len(nums)):
            num = nums[i]
            f = freq[i]
            current_count = count.get(num, 0)
            new_count = current_count + f

            # Update count_freq for the old count
            if current_count > 0:
                count_freq[current_count] -= 1
                if count_freq[current_count] == 0:
                    del count_freq[current_count]

            # Update the count and count_freq for the new count
            if new_count > 0:
                count[num] = new_count
                if new_count in count_freq:
                    count_freq[new_count] += 1
                else:
                    count_freq[new_count] = 1
                heapq.heappush(heap, -new_count)
            else:
                # Remove the ID from count if new_count is zero
                if num in count:
                    del count[num]

            # Determine the current maximum frequency
            current_max = 0
            while heap:
                candidate = -heap[0]
                if candidate in count_freq:
                    current_max = candidate
                    break
                else:
                    heapq.heappop(heap)
            ans.append(current_max)

        return ans

