class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        m = len(andValues)
        if m > n:
            return -1

        # Precompute and_list (1-based)
        and_list = [[] for _ in range(n + 1)]
        and_list[1] = [(nums[0], 1)]
        for i in range(2, n + 1):
            current_num = nums[i - 1]
            new_list = [(current_num, i)]
            for (prev_and, start_pos) in and_list[i - 1]:
                new_and = prev_and & current_num
                new_list.append((new_and, start_pos))
            # Deduplicate to keep the earliest start_pos for each and_val
            temp_dict = {}
            for and_val, start_pos in new_list:
                if and_val not in temp_dict or start_pos < temp_dict[and_val][1]:
                    temp_dict[and_val] = (and_val, start_pos)
            and_list[i] = list(temp_dict.values())

        INF = float('inf')
        # DP is (m+1) x (n+1), 1-based
        dp = [[INF] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = 0

        for j in range(1, m + 1):
            for i in range(1, n + 1):
                for (and_val, start_pos) in and_list[i]:
                    if and_val == andValues[j - 1]:
                        prev_pos = start_pos - 1
                        if prev_pos >= 0:
                            if dp[j - 1][prev_pos] + nums[i - 1] < dp[j][i]:
                                dp[j][i] = dp[j - 1][prev_pos] + nums[i - 1]

        return dp[m][n] if dp[m][n] != INF else -1

