class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        # Precompute LCM for all subsets and their bit counts
        lcm_list = [0] * (1 << n)
        bits_count = [0] * (1 << n)

        for mask in range(1, 1 << n):
            bits_count[mask] = bin(mask).count('1')
            lcm_val = 1
            for i in range(n):
                if mask & (1 << i):
                    c = coins[i]
                    g = math.gcd(lcm_val, c)
                    lcm_val = lcm_val // g * c
            lcm_list[mask] = lcm_val

        min_coin = min(coins)
        low = 1
        high = min_coin * k
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            cnt = 0
            for mask in range(1, 1 << n):
                s = bits_count[mask]
                lcm_val = lcm_list[mask]
                if lcm_val > mid:
                    continue
                term = mid // lcm_val
                if s % 2 == 1:
                    cnt += term
                else:
                    cnt -= term
            if cnt >= k:
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

class Node:
    __slots__ = ['children', 'min_length', 'earliest']
    def __init__(self):
        self.children = {}
        self.min_length = float('inf')
