class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums_sorted = sorted(nums)
        n = len(nums_sorted)
        m = n // 2
        cost = 0

        # Adjust the median element to k
        cost += abs(nums_sorted[m] - k)

        # Adjust elements before the median to be <= k
        for i in range(m):
            if nums_sorted[i] > k:
                cost += nums_sorted[i] - k

        # Adjust elements after the median to be >= k
        for i in range(m + 1, n):
            if nums_sorted[i] < k:
                cost += k - nums_sorted[i]

        return cost

