class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        dp0 = [[[0] * (limit + 1) for _ in range(one + 1)] for __ in range(zero + 1)]
        dp1 = [[[0] * (limit + 1) for _ in range(one + 1)] for __ in range(zero + 1)]

        if zero >= 1:
            dp0[1][0][1] = 1
        if one >= 1:
            dp1[0][1][1] = 1

        for i in range(zero + 1):
            for j in range(one + 1):
                for r in range(1, limit + 1):
                    # Process dp0[i][j][r]
                    val = dp0[i][j][r]
                    if val > 0:
                        # Add a 0
                        if i + 1 <= zero:
                            new_r = r + 1
                            if new_r <= limit:
                                dp0[i+1][j][new_r] = (dp0[i+1][j][new_r] + val) % MOD
                        # Add a 1
                        if j + 1 <= one:
                            dp1[i][j+1][1] = (dp1[i][j+1][1] + val) % MOD
                    # Process dp1[i][j][r]
                    val1 = dp1[i][j][r]
                    if val1 > 0:
                        # Add a 1
                        if j + 1 <= one:
                            new_r = r + 1
                            if new_r <= limit:
                                dp1[i][j+1][new_r] = (dp1[i][j+1][new_r] + val1) % MOD
                        # Add a 0
                        if i + 1 <= zero:
                            dp0[i+1][j][1] = (dp0[i+1][j][1] + val1) % MOD

        total = 0
        for r in range(1, limit + 1):
            total = (total + dp0[zero][one][r] + dp1[zero][one][r]) % MOD
        return total

