                upper_letters.add(c)
        count = 0
        for letter in 'abcdefghijklmnopqrstuvwxyz':
            if letter in lower_letters and letter.upper() in upper_letters:
                count += 1
        return count

class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        t_indices = {char: idx for idx, char in enumerate(t)}
        total_diff = 0
        for i in range(len(s)):
            char = s[i]
            t_index = t_indices[char]
            total_diff += abs(i - t_index)
        return total_diff

import math

class Solution:
    def waysToReachStair(self, k: int) -> int:
        total = 0
        for m in range(0, 40):  # Sufficient since 2^40 is way beyond 1e9
            pow2m = 1 << m  # Equivalent to 2^m
            d = pow2m - k
            if d < 0:
                continue
            if d > m + 1:
                continue
            total += math.comb(m + 1, d)
        return total

