    # Wait, actually, the second loop can be simplified. Maybe better to check all keys in the union of s_other and t_other.

    # Alternatively, a better way:
    # Check all keys present in either s_other or t_other
    # Create a set of all keys
    all_keys = set(s_other.keys()).union(t_other.keys())
    for k in all_keys:
