import heapq

def main():
    H, W, T = map(int, input().split())
    grid = []
    start = None
    goal = None
    candy_index = [[-1 for _ in range(W)] for _ in range(H)]
    candies = []
    candy_count = 0

    for i in range(H):
        line = input().strip()
        grid.append(line)
        for j in range(W):
            c = line[j]
            if c == 'S':
                start = (i, j)
            elif c == 'G':
                goal = (i, j)
            elif c == 'o':
                candy_index[i][j] = candy_count
                candies.append((i, j))
                candy_count += 1

    INF = float('inf')
    distance = [[dict() for _ in range(W)] for _ in range(H)]
    heap = []
    initial_mask = 0
    initial_steps = 0
    heapq.heappush(heap, (initial_steps, -initial_mask, start[0], start[1]))
    distance[start[0]][start[1]][initial_mask] = initial_steps

    max_mask = -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        steps, neg_mask, i, j = heapq.heappop(heap)
        mask = -neg_mask
        if (i, j) == goal:
            if steps <= T:
                if mask > max_mask:
                    max_mask = mask
            continue
        current_steps = distance[i][j].get(mask, INF)
        if steps > current_steps:
            continue
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < H and 0 <= nj < W:
                cell = grid[ni][nj]
                if cell == '#':
                    continue
                candy = candy_index[ni][nj]
                if candy != -1:
                    if not (mask & (1 << candy)):
                        new_mask = mask | (1 << candy)
                    else:
                        new_mask = mask
                else:
                    new_mask = mask
                new_steps = steps + 1
                if new_steps > T:
                    continue
                if new_mask in distance[ni][nj]:
                    if new_steps < distance[ni][nj][new_mask]:
                        distance[ni][nj][new_mask] = new_steps
                        heapq.heappush(heap, (new_steps, -new_mask, ni, nj))
                else:
                    distance[ni][nj][new_mask] = new_steps
                    heapq.heappush(heap, (new_steps, -new_mask, ni, nj))

    if max_mask == -1:
        print(-1)
    else:
        print(bin(max_mask).count('1'))

