        if current_state == 0:
            if c.isupper():
                A = ord(c) - ord('A') + 1
                return A
            else:
                return 0
        elif 1 <= current_state <= 26:
            A = chr(ord('A') + (current_state - 1))
            if c.isupper():
                if c == A:
                    return 27 + (current_state - 1)
                else:
                    new_A = ord(c) - ord('A') + 1
                    return new_A
            else:
                return current_state
        elif 27 <= current_state <= 52:
            A = chr(ord('A') + (current_state - 27))
            if c.islower():
                return 53 + (current_state - 27)
            else:
                return current_state
        elif 53 <= current_state <= 78:
            A = chr(ord('A') + (current_state - 53))
            if c.isupper():
                return -1
            else:
                return current_state
        else:
            assert False, "invalid state"

    for s in range(79):
        for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
            next_s = get_next_state(s, c)
            if next_s != -1:
                trans_upper[s][next_s] += 1
        for c in 'abcdefghijklmnopqrstuvwxyz':
            next_s = get_next_state(s, c)
            if next_s != -1:
