    stack = []
    pairs = []
    for i, c in enumerate(S):
        if c == '(':
            stack.append(i)
        elif c == ')':
            if stack:
                start = stack.pop()
                pairs.append((start, i))
    # Merge intervals
    merged = []
    for s, e in pairs:
        if not merged:
            merged.append((s, e))
        else:
            last_s, last_e = merged[-1]
            if s <= last_e:
                new_s = min(last_s, s)
                new_e = max(last_e, e)
                merged.pop()
                merged.append((new_s, new_e))
            else:
                merged.append((s, e))
    # Build result
    res = []
    i = 0
    interval_ptr = 0
    n = len(merged)
    while i < N:
        if interval_ptr < n:
            current_start, current_end = merged[interval_ptr]
            if i < current_start:
                res.append(S[i])
                i += 1
            elif i <= current_end:
                i += 1
            else:
                interval_ptr += 1
        else:
            res.append(S[i])
            i += 1
    print(''.join(res))

