def main():
    import sys
    N, T, M = map(int, sys.stdin.readline().split())
    incompatible_pairs = []
    for _ in range(M):
        a, b = map(int, sys.stdin.readline().split())
        incompatible_pairs.append((a-1, b-1))  # Convert to 0-based indices

    all_rgs = []
    def backtrack(current, current_max):
        if len(current) == N:
            all_rgs.append(current.copy())
            return
        next_pos = len(current)
        if next_pos == 0:
            current.append(0)
            backtrack(current, 0)
            current.pop()
        else:
            for choice in range(0, current_max + 2):
                current.append(choice)
                new_max = max(current_max, choice)
                backtrack(current, new_max)
                current.pop()

    backtrack([], 0)

    count = 0
    for rgs in all_rgs:
        if max(rgs) != T - 1:
            continue
        valid = True
        for a, b in incompatible_pairs:
            if rgs[a] == rgs[b]:
                valid = False
                break
        if valid:
            count += 1
    print(count)

