import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    prerequisites = [[] for _ in range(N+1)]
    reversed_adj = [[] for _ in range(N+1)]
    original_adj = [[] for _ in range(N+1)]
    for i in range(1, N+1):
        parts = list(map(int, sys.stdin.readline().split()))
        C_i = parts[0]
        P_list = parts[1:]
        prerequisites[i] = P_list
        reversed_adj[i] = P_list[:]
        for p in P_list:
            original_adj[p].append(i)

    # Find required nodes (excluding book1)
    visited = [False] * (N+1)
    required = [False] * (N+1)
    q = deque()
    q.append(1)
    visited[1] = True
    while q:
        u = q.popleft()
        if u != 1:
            required[u] = True
        for v in reversed_adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    # Compute in_degree for required nodes
    in_degree = [0] * (N+1)
    for u in range(1, N+1):
        if required[u]:
            for p in prerequisites[u]:
                if required[p]:
                    in_degree[u] += 1

    # Kahn's algorithm
    order = []
    kahn_q = deque()
    for u in range(1, N+1):
        if required[u] and in_degree[u] == 0:
            kahn_q.append(u)

    while kahn_q:
        u = kahn_q.popleft()
        order.append(u)
        for v in original_adj[u]:
            if required[v]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    kahn_q.append(v)

    print(' '.join(map(str, order)))

