def main():
    lines = [line.strip() for line in sys.stdin]

    # Read the three polyominoes
    polys = []
    for i in 0, 4, 8:
        coords = []
        for row in range(4):
            line = lines[i + row]
            for col in range(4):
                if line[col] == '#':
                    coords.append((row, col))
        polys.append(coords)

    # Check area sum
    areas = [len(p) for p in polys]
    if sum(areas) != 16:
        print("No")
        return

    # Function to generate placements for a given poly's coordinates
    def generate_placements(coords):
        placements = []
        for rotation in 0, 1, 2, 3:
            if rotation == 0:
                rotated = coords
            elif rotation == 1:
                rotated = [(y, 3 - x) for (x, y) in coords]
            elif rotation == 2:
                rotated = [(3 - x, 3 - y) for (x, y) in coords]
            else:  # rotation 3 (270)
                rotated = [(3 - y, x) for (x, y) in coords]

            # Normalize the rotated coordinates
            min_x = min(x for x, y in rotated)
            min_y = min(y for x, y in rotated)
            normalized = [(x - min_x, y - min_y) for (x, y) in rotated]

            # Determine max_x and max_y
            max_x = max(x for x, y in normalized)
            max_y = max(y for x, y in normalized)

            # Possible dx and dy ranges
            dx_range = range(0, (3 - max_x) + 1)
            dy_range = range(0, (3 - max_y) + 1)

            for dx in dx_range:
                for dy in dy_range:
                    translated = [(x + dx, y + dy) for (x, y) in normalized]
                    placements.append(frozenset(translated))
        return placements

    # Generate placements for each poly
