        for p2 in placements2:
            len_p1 = len(p1)
            len_p2 = len(p2)
            total = len_p1 + len_p2
            if total > 16 or not p1.isdisjoint(p2):
                continue
            needed = 16 - total
            if needed < 0 or needed not in p3_dict:
                continue
            for p3 in p3_dict[needed]:
                if p3.isdisjoint(p1) and p3.isdisjoint(p2):
                    print("Yes")
