def main():
    input = sys.stdin.read().split('\n')
    first_line = input[0].split()
    N = int(first_line[0])
    T_prime = first_line[1]
    S_list = []
    for i in range(1, N+1):
        s = input[i].strip()
        S_list.append(s)

    valid_indices = []

    for idx in range(N):
        s = S_list[idx]
        if s == T_prime:
            valid_indices.append(idx + 1)
            continue
        len_s = len(s)
        len_t = len(T_prime)
        if abs(len_s - len_t) > 1:
            continue
        if len_s == len_t - 1:
            # Check insertion case: s is shorter, check if can be formed by deleting one from T'
            n = len_s
            m = len_t
            i = j = 0
            diff = 0
            valid = True
            while i < n and j < m:
                if s[i] == T_prime[j]:
                    i += 1
                    j += 1
                else:
                    j += 1
                    diff += 1
                    if diff > 1:
                        valid = False
                        break
            if i < n:
                valid = False
            if valid:
                valid_indices.append(idx + 1)
        elif len_s == len_t + 1:
            # Check deletion case: s is longer, check if T' can be formed by deleting one from s
            n = len_s
            m = len_t
            i = j = 0
            diff = 0
            valid = True
            while i < n and j < m:
                if s[i] == T_prime[j]:
                    i += 1
                    j += 1
                else:
                    i += 1
                    diff += 1
                    if diff > 1:
                        valid = False
                        break
            if j < m:
                valid = False
            if valid:
                valid_indices.append(idx + 1)
        else:
            # Same length, check substitution
            diff = 0
            for a, b in zip(s, T_prime):
                if a != b:
                    diff += 1
                    if diff > 1:
                        break
            if diff == 1:
                valid_indices.append(idx + 1)

    print(len(valid_indices))
    if valid_indices:
        print(' '.join(map(str, valid_indices)))
    else:
        print()

