    high = max_bc

    def is_possible(r):
        dp = [ -float('inf') ] * (N+1)
        dp[1] = 0.0
        for u in range(1, N+1):
            if dp[u] == -float('inf'):
                continue
            for (v, b, c) in edges[u]:
                new_val = dp[u] + (b - r * c)
                if new_val > dp[v]:
                    dp[v] = new_val
        return dp[N] >= 0.0

    for _ in range(100):
        mid = (low + high) / 2
        if is_possible(mid):
            low = mid
        else:
            high = mid

    ans = (low + high) / 2
    print("{0:.15f}".format(ans))

