def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    D = list(map(int, sys.stdin.readline().split()))
    L1, C1, K1 = map(int, sys.stdin.readline().split())
    L2, C2, K2 = map(int, sys.stdin.readline().split())

    sections = []
    possible = True

    for d in D:
        options = []
        max_x = min((d + L1 - 1) // L1, K1)
        for x in range(0, max_x + 1):
            remaining = d - x * L1
            if remaining <= 0:
                y = 0
            else:
                y = (remaining + L2 - 1) // L2
            if y > K2:
                continue
            if x * L1 + y * L2 >= d:
                cost = x * C1 + y * C2
                options.append((x, y, cost))
        if not options:
            possible = False
            break
        sections.append(options)
    if not possible:
        print(-1)
        return

    INF = float('inf')
    dp = [(INF, INF) for _ in range(K1 + 1)]
    dp[0] = (0, 0)

    for options in sections:
        new_dp = [(INF, INF) for _ in range(K1 + 1)]
        for a in range(K1 + 1):
            current = dp[a]
            if current[0] == INF:
                continue
            current_cost, current_b = current
            for x, y, cost in options:
                new_a = a + x
                new_b = current_b + y
                new_total = current_cost + cost
                if new_a > K1 or new_b > K2:
                    continue
                if new_total < new_dp[new_a][0] or (new_total == new_dp[new_a][0] and new_b < new_dp[new_a][1]):
                    new_dp[new_a] = (new_total, new_b)
        dp = new_dp

    min_cost = INF
    for a in range(K1 + 1):
        cost, b = dp[a]
        if cost < min_cost:
            min_cost = cost

    if min_cost == INF:
        print(-1)
    else:
        print(min_cost)

