from itertools import permutations, combinations, permutations as perm

def main():
    N = int(sys.stdin.readline())
    R = sys.stdin.readline().strip()
    C = sys.stdin.readline().strip()

    found = False
    for p in permutations(range(N)):
        p_inv = [0] * N
        for i in range(N):
            j = p[i]
            p_inv[j] = i
        valid = True
        for j in range(N):
            if C[j] != R[p_inv[j]]:
                valid = False
                break
        if not valid:
            continue

        grid = [['.'] * N for _ in range(N)]
        for i in range(N):
            j_col = p[i]
            grid[i][j_col] = R[i]

        def backtrack(current_grid, row):
            if row == N:
                for j in range(N):
                    col_letters = set()
                    for i in range(N):
                        c = current_grid[i][j]
                        if c != '.':
                            col_letters.add(c)
                    if len(col_letters) != 3:
                        return None
                return [row.copy() for row in current_grid]
            current_row = current_grid[row]
            placed_char = current_row[p[row]]
            remaining = [c for c in ['A', 'B', 'C'] if c != placed_char]
            available = []
            for j in range(N):
                if j > p[row] and p_inv[j] <= row:
                    available.append(j)
            for cols in combinations(available, 2):
                for letters in perm(remaining):
                    c1, c2 = letters
                    has_c1 = False
                    for i in range(N):
                        if current_grid[i][cols[0]] == c1:
                            has_c1 = True
                            break
                    if has_c1:
                        continue
                    has_c2 = False
                    for i in range(N):
                        if current_grid[i][cols[1]] == c2:
                            has_c2 = True
                            break
                    if has_c2:
                        continue
                    new_grid = [r.copy() for r in current_grid]
                    new_grid[row][cols[0]] = c1
                    new_grid[row][cols[1]] = c2
                    result = backtrack(new_grid, row + 1)
                    if result is not None:
                        return result
            return None

        result = backtrack(grid, 0)
        if result is not None:
            valid_rows = True
            for row in result:
                cnt = {'A': 0, 'B': 0, 'C': 0}
                for c in row:
                    if c in cnt:
                        cnt[c] += 1
                if cnt['A'] != 1 or cnt['B'] != 1 or cnt['C'] != 1:
                    valid_rows = False
                    break
            if valid_rows:
                print("Yes")
                for row in result:
                    print(''.join(row))
                return

    print("No")

