import sys
import itertools

def main():
    N, M, K = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(M):
        u, v, w = map(int, sys.stdin.readline().split())
        edges.append((u, v, w))

    min_mod = K  # Initialize with a value larger than any possible mod
    required_edges = N - 1

    for combo in itertools.combinations(edges, required_edges):
        parent = list(range(N + 1))  # 1-based indexing

        # Process each edge in the combination to perform unions
        for u, v, w in combo:
            # Find root of u
            pu = u
            while parent[pu] != pu:
                pu = parent[pu]
            # Find root of v
            pv = v
            while parent[pv] != pv:
                pv = parent[pv]
            if pu != pv:
                parent[pv] = pu

        # Check if all nodes are connected
        root = 1
        while parent[root] != root:
            root = parent[root]
        connected = True
        for node in range(2, N + 1):
            r = node
            while parent[r] != r:
                r = parent[r]
            if r != root:
                connected = False
                break

        if connected:
            total = sum(w for _, _, w in combo)
            current_mod = total % K
            if current_mod < min_mod:
                min_mod = current_mod

    print(min_mod)

