import sys
from collections import deque

def main():
    MOD = 998244353
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    component = [[0] * W for _ in range(H)]
    original_C = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#' and component[i][j] == 0:
                original_C += 1
                current_id = original_C
                q = deque()
                q.append((i, j))
                component[i][j] = current_id
                while q:
                    x, y = q.popleft()
                    for dx, dy in directions:
                        nx = x + dx
                        ny = y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if grid[nx][ny] == '#' and component[nx][ny] == 0:
                                component[nx][ny] = current_id
                                q.append((nx, ny))

    R = sum(row.count('.') for row in grid)
    if R == 0:
        print(0)
        return

    sum_delta = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                adj_components = set()
                for dx, dy in directions:
                    nx = i + dx
                    ny = j + dy
                    if 0 <= nx < H and 0 <= ny < W:
                        if grid[nx][ny] == '#':
                            adj_components.add(component[nx][ny])
                k = len(adj_components)
                delta = 1 - k
                sum_delta += delta

    numerator = (original_C * R + sum_delta) % MOD
    denominator = R
    denominator_inv = pow(denominator, MOD - 2, MOD)
    ans = (numerator * denominator_inv) % MOD
    print(ans)

