import array

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(N)]
    for _ in range(M):
        u, v, w = map(int, sys.stdin.readline().split())
        u -= 1
        v -= 1
        edges[u].append((v, w))

    # Check if there's a node from which all others are reachable
    found = False
    for start in range(N):
        visited = [False] * N
        stack = [start]
        visited[start] = True
        while stack:
            u = stack.pop()
            for v, _ in edges[u]:
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)
        if all(visited):
            found = True
            break
    if not found:
        print("No")
        return

    # Proceed with DP
    INF = float('inf')
    full_mask = (1 << N) - 1
    dp = [None] * (1 << N)
    for mask in range(1 << N):
        dp[mask] = array.array('d', [INF] * N)
    for u in range(N):
        mask = 1 << u
        dp[mask][u] = 0.0

    masks = sorted([mask for mask in range(1 << N)], key=lambda x: bin(x).count('1'))

    for mask in masks:
        for u in range(N):
            current_cost = dp[mask][u]
            if current_cost == INF:
                continue
            for (v, w) in edges[u]:
                new_mask = mask | (1 << v)
                new_cost = current_cost + w
                if new_cost < dp[new_mask][v]:
                    dp[new_mask][v] = new_cost

    result = INF
    for v in range(N):
        if dp[full_mask][v] < result:
            result = dp[full_mask][v]

    if result == INF:
        print("No")
    else:
        print(int(result) if result == int(result) else result)

