from collections import deque

def main():
    import sys
    N = int(sys.stdin.readline())
    grid = [sys.stdin.readline().strip() for _ in range(N)]

    p1 = p2 = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'P':
                if p1 is None:
                    p1 = (i, j)
                else:
                    p2 = (i, j)

    # Canonical form for initial state
    a = p1
    b = p2
    if a <= b:
        start = (a[0], a[1], b[0], b[1])
    else:
        start = (b[0], b[1], a[0], a[1])

    visited = set()
    visited.add(start)
    queue = deque()
    queue.append(start)
    steps = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while queue:
        level_size = len(queue)
        for _ in range(level_size):
            r1, c1, r2, c2 = queue.popleft()

            # Check if current positions are the same
            if (r1, c1) == (r2, c2):
                print(steps)
                return

            for dr, dc in directions:
                # Compute new positions for both players
                new_r1, new_c1 = r1 + dr, c1 + dc
                if not (0 <= new_r1 < N and 0 <= new_c1 < N) or grid[new_r1][new_c1] == '#':
                    new_r1, new_c1 = r1, c1

                new_r2, new_c2 = r2 + dr, c2 + dc
                if not (0 <= new_r2 < N and 0 <= new_c2 < N) or grid[new_r2][new_c2] == '#':
                    new_r2, new_c2 = r2, c2

                # Check if new positions are the same
                if (new_r1, new_c1) == (new_r2, new_c2):
                    print(steps + 1)
                    return

                # Create canonical state
                a_new = (new_r1, new_c1)
                b_new = (new_r2, new_c2)
                if a_new <= b_new:
                    new_state = (new_r1, new_c1, new_r2, new_c2)
                else:
                    new_state = (new_r2, new_c2, new_r1, new_c1)

                if new_state not in visited:
                    visited.add(new_state)
                    queue.append(new_state)

        steps += 1

    print(-1)

