def main():
    import sys
    H, W, N = map(int, sys.stdin.readline().split())
    T = sys.stdin.readline().strip()
    reversed_T = T[::-1]
    S = [sys.stdin.readline().strip() for _ in range(H)]

    # Precompute is_land as a list of lists of booleans
    is_land = []
    for row in S:
        is_row = [c == '.' for c in row]
        is_land.append(is_row)

    # Compute land_mask for each row
    land_mask = [0] * H
    for i in range(H):
        mask = 0
        for j in range(W):
            if is_land[i][j]:
                mask |= (1 << j)
        land_mask[i] = mask

    # Initialize prev_bits as land_mask
    prev_bits = land_mask.copy()

    for direction in reversed_T:
        current_bits = [0] * H
        if direction == 'L':
            for i in range(H):
                current_bits[i] = (prev_bits[i] << 1) & land_mask[i]
        elif direction == 'R':
            for i in range(H):
                current_bits[i] = (prev_bits[i] >> 1) & land_mask[i]
        elif direction == 'U':
            for i in range(H):
                if i + 1 < H:
                    current_bits[i] = (prev_bits[i + 1] & land_mask[i])
                else:
                    current_bits[i] = 0
        elif direction == 'D':
            for i in range(H):
                if i - 1 >= 0:
                    current_bits[i] = (prev_bits[i - 1] & land_mask[i])
                else:
                    current_bits[i] = 0
        prev_bits = current_bits

    # Count the number of set bits in all rows
    count = 0
    for mask in prev_bits:
        count += bin(mask).count('1')

    print(count)

