import sys
from collections import defaultdict

def main():
    max_num = 200000
    spf = [0] * (max_num + 1)
    spf[0] = 0
    spf[1] = 1
    for i in range(2, max_num + 1):
        if spf[i] == 0:
            spf[i] = i
            for j in range(i * i, max_num + 1, i):
                if spf[j] == 0:
                    spf[j] = i

    def factor(n):
        factors = {}
        while n > 1:
            p = spf[n]
            count = 0
            while n % p == 0:
                count += 1
                n = n // p
            factors[p] = count
        return factors

    def square_free(n):
        if n == 0:
            return 0
        factors = factor(n)
        res = 1
        for p in factors:
            if factors[p] % 2 == 1:
                res *= p
        return res

    data = list(map(int, sys.stdin.read().split()))
    N = data[0]
    A = data[1:N+1]
    Z = A.count(0)
    non_zero = [x for x in A if x != 0]

    counts = defaultdict(int)
    for x in non_zero:
        s = square_free(x)
        counts[s] += 1

    non_zero_pairs = 0
    for c in counts.values():
        non_zero_pairs += c * (c - 1) // 2

    zero_pairs = Z * (N - Z) + Z * (Z - 1) // 2
    print(zero_pairs + non_zero_pairs)

