import sys
import heapq

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    edges_in = [[] for _ in range(N + 1)]  # 1-based indexing

    for _ in range(M):
        l_i, d_i, k_i, c_i, A_i, B_i = map(int, sys.stdin.readline().split())
        edges_in[B_i].append((A_i, l_i, d_i, k_i, c_i))

    INF = 10**18 + 1
    f = [-INF] * (N + 1)
    f[N] = INF

    heap = [(-f[N], N)]
    heapq.heapify(heap)

    while heap:
        current_neg_f, current_node = heapq.heappop(heap)
        current_f = -current_neg_f
        if current_f < f[current_node]:
            continue

        for edge in edges_in[current_node]:
            A, l, d, k, c = edge
            desired_t = current_f - c
            if desired_t < l:
                continue
            numerator = desired_t - l
            if numerator < 0:
                continue
            m_max = numerator // d
            m_max = min(m_max, k - 1)
            if m_max < 0:
                continue
            t_candidate = l + m_max * d
            if t_candidate > f[A]:
                f[A] = t_candidate
                heapq.heappush(heap, (-f[A], A))

    for S in range(1, N):
        if f[S] == -INF:
            print("Unreachable")
        else:
            print(f[S])

