def has_subset_with_sum(tiles, target):
    N = len(tiles)
    for mask in range(0, 1 << N):
        s = 0
        for i in range(N):
            if (mask >> i) & 1:
                a, b = tiles[i]
                s += a * b
        if s == target:
            return True
    return False

def find_first_empty(grid, H, W):
    for i in range(H):
        for j in range(W):
            if not grid[i][j]:
                return (i, j)
    return None

def backtrack(grid, used, tiles, H, W):
    pos = find_first_empty(grid, H, W)
    if pos is None:
        return True
    x, y = pos
    for i in range(len(tiles)):
        if not used[i]:
            a, b = tiles[i]
            for h, w in [(a, b), (b, a)]:
                if x + h > H or y + w > W:
                    continue
                valid = True
                for dx in range(h):
                    for dy in range(w):
                        if grid[x + dx][y + dy]:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    # Mark the cells
                    for dx in range(h):
                        for dy in range(w):
                            grid[x + dx][y + dy] = True
                    used[i] = True
                    if backtrack(grid, used, tiles, H, W):
                        return True
                    # Undo
                    for dx in range(h):
                        for dy in range(w):
                            grid[x + dx][y + dy] = False
                    used[i] = False
    return False

