def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    S = sys.stdin.readline().strip()
    C = list(map(int, sys.stdin.readline().split()))

    cost_0 = [0] * (N + 1)  # 1-based
    cost_1 = [0] * (N + 1)
    for j in range(1, N + 1):
        c = S[j - 1]
        if c == '0':
            cost_0[j] = 0
            cost_1[j] = C[j - 1]
        else:
            cost_0[j] = C[j - 1]
            cost_1[j] = 0

    # Compute left_cost0 and left_cost1
    left_cost0 = [0] * (N + 1)
    left_cost1 = [0] * (N + 1)
    for j in range(1, N + 1):
        parity = (j - 1) % 2
        required_bit0 = 0 if parity == 0 else 1
        required_bit1 = 1 if parity == 0 else 0

        # left_cost0[j]
        if required_bit0 == 0:
            term0 = cost_0[j]
        else:
            term0 = cost_1[j]
        left_cost0[j] = left_cost0[j - 1] + term0

        # left_cost1[j]
        if required_bit1 == 1:
            term1 = cost_1[j]
        else:
            term1 = cost_0[j]
        left_cost1[j] = left_cost1[j - 1] + term1

    # Compute right_cost0 and right_cost1
    right_cost0 = [0] * (N + 2)  # up to N+1
    right_cost1 = [0] * (N + 2)
    for k in range(N, 0, -1):
        right_cost0[k] = cost_0[k] + right_cost1[k + 1]
        right_cost1[k] = cost_1[k] + right_cost0[k + 1]

    min_total = float('inf')
    for i in range(1, N):  # i from 1 to N-1 inclusive
        for X in [0, 1]:
            parity = (i - 1) % 2
            if parity == 0:
                # starting_bit is X
                if X == 0:
                    left = left_cost0[i]
                else:
                    left = left_cost1[i]
            else:
                starting_bit = 1 - X
                if starting_bit == 0:
                    left = left_cost0[i]
                else:
                    left = left_cost1[i]

            if X == 0:
                right = right_cost0[i + 1]
            else:
                right = right_cost1[i + 1]

            total = left + right
            if total < min_total:
                min_total = total

    print(min_total)

