import sys
from functools import lru_cache

def main():
    A = []
    for _ in range(3):
        row = list(map(int, sys.stdin.readline().split()))
        A.append(row)

    initial_grid = ((0, 0, 0), (0, 0, 0), (0, 0, 0))

    @lru_cache(maxsize=None)
    def determine_winner(grid_tuple, is_takahashi_turn):
        current_player = "Takahashi" if is_takahashi_turn else "Aoki"
        current_color = 1 if is_takahashi_turn else 2
        grid = [list(row) for row in grid_tuple]

        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    new_grid = [row.copy() for row in grid]
                    new_grid[i][j] = current_color
                    new_grid_tuple = tuple(map(tuple, new_grid))

                    if has_three_in_row(new_grid_tuple, current_color):
                        return current_player

                    filled = True
                    for row in new_grid:
                        if 0 in row:
                            filled = False
                            break
                    if filled:
                        tak_score = 0
                        aoki_score = 0
                        for x in range(3):
                            for y in range(3):
                                if new_grid[x][y] == 1:
                                    tak_score += A[x][y]
                                elif new_grid[x][y] == 2:
                                    aoki_score += A[x][y]
                        if tak_score > aoki_score:
                            winner = "Takahashi"
                        else:
                            winner = "Aoki"
                        return winner

                    next_result = determine_winner(new_grid_tuple, not is_takahashi_turn)
                    if next_result == current_player:
                        return current_player

        return "Aoki" if is_takahashi_turn else "Takahashi"

    def has_three_in_row(grid, color):
        for row in grid:
            if all(cell == color for cell in row):
                return True
        for col in range(3):
            if all(grid[row][col] == color for row in range(3)):
                return True
        if all(grid[i][i] == color for i in range(3)):
            return True
        if all(grid[i][2 - i] == color for i in range(3)):
            return True
        return False

    result = determine_winner(initial_grid, True)
    print(result)

