import sys
from collections import deque

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        s = sys.stdin.readline().strip()
        grid.append(list(s))

    # Initialize free array
    free = [[False for _ in range(W)] for _ in range(H)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                free[i][j] = False
            else:
                is_free = True
                for dx, dy in directions:
                    ni = i + dx
                    nj = j + dy
                    if 0 <= ni < H and 0 <= nj < W:
                        if grid[ni][nj] == '#':
                            is_free = False
                            break
                free[i][j] = is_free

    visited = [[False for _ in range(W)] for _ in range(H)]
    max_total = 1  # Minimum possible is 1 for blocked cells

    for i in range(H):
        for j in range(W):
            if not visited[i][j] and free[i][j]:
                q = deque()
                q.append((i, j))
                visited[i][j] = True
                component_size = 0
                adj_set = set()

                while q:
                    x, y = q.popleft()
                    component_size += 1
                    for dx, dy in directions:
                        nx = x + dx
                        ny = y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if free[nx][ny] and not visited[nx][ny]:
                                visited[nx][ny] = True
                                q.append((nx, ny))
                            else:
                                # Check if the cell is '.' and not part of the component
                                if grid[nx][ny] == '.' and not visited[nx][ny]:
                                    adj_set.add((nx, ny))
                        else:
                            continue  # Out of grid, ignore

                total = component_size + len(adj_set)
                if total > max_total:
                    max_total = total

    print(max_total)

