import sys

def main():
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    operations = []
    for _ in range(M):
        parts = sys.stdin.readline().split()
        K_i = int(parts[0])
        C_i = int(parts[1])
        A_list = list(map(int, sys.stdin.readline().split()))
        operations.append((C_i, K_i, A_list))

    operations.sort()

    parent = list(range(N + 1))
    rank = [1] * (N + 1)

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
            rank[v_root] += rank[u_root]
        else:
            parent[v_root] = u_root
            rank[u_root] += rank[v_root]

    total = 0
    for C, K, A in operations:
        roots = set()
        for a in A:
            roots.add(find(a))
        roots_list = list(roots)
        k = len(roots_list)
        if k >= 1:
            total += (k - 1) * C
            if k > 1:
                target = roots_list[0]
                for r in roots_list[1:]:
                    union(target, r)

    # Check if all nodes are connected
    root = find(1)
    connected = True
    for node in range(2, N + 1):
        if find(node) != root:
            connected = False
            break
    if not connected:
        print(-1)
    else:
        print(total)

