from collections import deque

class TrieNode:
    __slots__ = ['children', 'count']
    def __init__(self):
        self.children = [None] * 26
        self.count = 0

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    strings = input[1:N+1]

    root = TrieNode()
    for s in strings:
        current = root
        current.count += 1
        for c in s:
            idx = ord(c) - ord('a')
            if current.children[idx] is None:
                current.children[idx] = TrieNode()
            current = current.children[idx]
            current.count += 1

    total = 0
    q = deque([root])
    while q:
        node = q.popleft()
        for child in node.children:
            if child is not None:
                total += child.count * (child.count - 1) // 2
                q.append(child)
    print(total)

